using System;
using System.Collections.Generic;

namespace StardewValley.Pokemon;

public class PokemonSpecies
{
	public int DexNumber { get; set; }
	public int PokedexNumber => DexNumber;
	public string Name { get; set; }
	public string InternalName { get; set; } // Matches pokeemerald/pokeplatinum/pokeemerald-expansion pokemon folder
	public string BaseSpeciesName { get; set; }
	public bool IsMega { get; set; } = false;
	public bool IsAlternateForm { get; set; } = false;
	public bool HasGigantamax { get; set; } = false;
	public PokemonType PrimaryType { get; set; }
	public PokemonType? SecondaryType { get; set; }
	public int BaseHP { get; set; }
	public int BaseAttack { get; set; }
	public int BaseDefense { get; set; }
	public int BaseSpAttack { get; set; }
	public int BaseSpDefense { get; set; }
	public int BaseSpeed { get; set; }
	public int CatchRate { get; set; } = 45;
	public int BaseExpYield { get; set; } = 100;
	public List<string> LearnableMoves { get; set; } = new();

	private static readonly Dictionary<string, PokemonSpecies> _registry = new(StringComparer.OrdinalIgnoreCase);

	public static void Register(PokemonSpecies species)
	{
		if (PokemonRates.Rates.TryGetValue(species.InternalName, out var rate) || PokemonRates.Rates.TryGetValue(species.Name, out rate))
		{
			species.CatchRate = rate.CatchRate;
			species.BaseExpYield = rate.BaseExpYield;
		}
		_registry[species.Name] = species;
		_registry[species.InternalName] = species;
	}

	public static List<PokemonSpecies> AllSpecies()
	{
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		var list = new List<PokemonSpecies>();
		foreach (var s in _registry.Values)
		{
			if (s.IsMega || s.IsAlternateForm) continue;
			if (seen.Add(s.InternalName)) list.Add(s);
		}
		list.Sort((a, c) => a.DexNumber.CompareTo(c.DexNumber));
		return list;
	}

	public static List<PokemonSpecies> AllMegaSpecies()
	{
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		var list = new List<PokemonSpecies>();
		foreach (var s in _registry.Values)
		{
			if (!s.IsMega && !s.IsAlternateForm) continue;
			if (seen.Add(s.InternalName)) list.Add(s);
		}
		list.Sort((a, c) =>
		{
			int cmp = a.DexNumber.CompareTo(c.DexNumber);
			return cmp != 0 ? cmp : string.Compare(a.InternalName, c.InternalName, StringComparison.OrdinalIgnoreCase);
		});
		return list;
	}

	public static List<PokemonSpecies> GetMegaForms(string baseInternalOrName)
	{
		var list = new List<PokemonSpecies>();
		if (string.IsNullOrEmpty(baseInternalOrName)) return list;
		var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (var s in _registry.Values)
		{
			if (!s.IsMega) continue;
			if (string.Equals(s.BaseSpeciesName, baseInternalOrName, StringComparison.OrdinalIgnoreCase))
			{
				if (seen.Add(s.InternalName)) list.Add(s);
			}
		}
		list.Sort((a, b) => string.Compare(a.InternalName, b.InternalName, StringComparison.OrdinalIgnoreCase));
		return list;
	}

	public static PokemonSpecies Get(string name)
	{
		if (_registry.TryGetValue(name, out var species))
		{
			return species;
		}
		// Default fallback
		return new PokemonSpecies
		{
			DexNumber = 25,
			Name = name,
			InternalName = name.ToLowerInvariant(),
			PrimaryType = PokemonType.Normal,
			BaseHP = 50,
			BaseAttack = 50,
			BaseDefense = 50,
			BaseSpAttack = 50,
			BaseSpDefense = 50,
			BaseSpeed = 50,
			CatchRate = 45,
			BaseExpYield = 100
		};
	}

